/*
 * A074912  Triangle generated by Pascal's rule, except begin and end the n-th
 *          row with phi(n).
 * https://oeis.org/A074912
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   Triangle generated by Pascal's rule, except begin and end each
 *            row with φ(n). The sequence a(n) is the entries of this triangle
 *            read row by row (offset 1). For any n ≥ 1 the function computes
 *            a(n) on demand, caching generated rows for future calls
 * Range:     u8 n <= 59, u16 n <= 66, u32 n <= 66, u64 n <= 66, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

/* Euler's totient φ(n) for n ≥ 1.  Uses a simple trial division
   algorithm and fits in seq_t. */
static seq_t phi(idx_t n)
{
    if (n < 2) return 1;          /* φ(1) = 1, φ(0) not used */
    seq_t res = n;
    idx_t t = n;
    for (idx_t p = 2; p * p <= t; ++p)
    {
        if (t % p == 0)
        {
            while (t % p == 0) t /= p;
            res -= res / p;
        }
    }
    if (t > 1) res -= res / t;
    return res;
}

/* Return the a(n) term for the triangle sequence A074912. */
seq_t a(idx_t n)
{
    /* Find the row r containing the n-th term:
       row indices start at 1, row r has r terms,
       cumulative count up to row r is r*(r+1)/2. */
    idx_t r = 1;
    while (r * (r + 1) / 2 < n) ++r;
    idx_t prev = r * (r - 1) / 2;          /* terms before row r */
    idx_t p = n - prev;                    /* column (1‑based) in row r */

    /* Static cache of generated rows: rows[1] … rows[r] */
    static seq_t **rows = NULL;        /* array of row pointers */
    static idx_t rows_alloc = 0;       /* allocated number of row slots */
    static idx_t rows_used  = 0;       /* highest row index generated */

    /* Expand the rows array if necessary */
    if (r > rows_alloc)
    {
        idx_t new_alloc = rows_alloc ? rows_alloc << 1 : 2;
        while (new_alloc < r) new_alloc <<= 1;
        seq_t **tmp = (seq_t **)realloc(rows, new_alloc * sizeof(seq_t *));
        if (!tmp) exit(EXIT_FAILURE);
        rows = tmp;
        rows_alloc = new_alloc;
    }

    /* Generate rows that have not yet been created */
    for (idx_t k = rows_used + 1; k <= r; ++k)
    {
        /* Allocate one‑based array of size k+1 (ignore index 0) */
        seq_t *row = (seq_t *)malloc((k + 1) * sizeof(seq_t));
        if (!row) exit(EXIT_FAILURE);
        /* First and last entries are φ(k) */
        seq_t phi_k = phi(k);
        row[1] = phi_k;
        row[k] = phi_k;
        /* Interior entries via Pascal's rule */
        if (k > 2)
        {
            seq_t *prev_row = rows[k - 1];
            for (idx_t j = 2; j <= k - 1; ++j)
                row[j] = prev_row[j - 1] + prev_row[j];
        }
        rows[k] = row;
        rows_used = k;
    }

    /* Return the requested element */
    if (p == 1 || p == r)
        return phi(r);
    else
        return rows[r][p];
}
